UPDATE
	WALKING_THRU_RECORD
SET
	password = #{password}
WHERE
	homepage_id = #{homepage_id}
AND request_number = #{request_number}
AND cancel_yn = 'N'
AND TO_DATE(TO_CHAR(SYSDATE, 'YYYY/MM/DD'), 'YYYY/MM/DD') = TO_DATE(request_date, 'YYYY/MM/DD')

UPDATE
	WALKING_THRU_RECORD
SET
	password = #{password}
WHERE
	homepage_id = #{homepage_id}
AND request_number = #{request_number}
AND cancel_yn = 'N'
AND TO_DATE(TO_CHAR(TO_DATE(SYSDATE, 'YYYY/MM/DD') - INTERVAL '1' DAY, 'YYYY/MM/DD'), 'YYYY/MM/DD') = TO_DATE(request_date, 'YYYY/MM/DD')
